 row.append(thumb,name,actions,opacity);row.onclick=e=>{if(e.shiftKey&&state.selected){const a=state.layers.findIndex(q=>q.id===state.selected),b=state.layers.indexOf(l);if(a>=0)for(const item of state.layers.slice(Math.min(a,b),Math.max(a,b)+1))state.multi.add(item.id);}else if(e.ctrlKey||e.metaKey){state.multi.has(l.id)?state.multi.delete(l.id):state.multi.add(l.id);state.selected=l.id;state.mode=!l.locked?'edit':'normal';updateControls()}else selectLayer(l.id)};
