function deleteSelected(){const ids=state.multi.size?[...state.multi]:state.selected?[state.selected]:[];if(!ids.length)return;const count=ids.length;if(!confirm(`¿Eliminar ${count===1?'la capa seleccionada':`${count} capas seleccionadas`}? Los archivos originales se conservan.`))return;state.layers=state.layers.filter(l=>!ids.includes(l.id));for(const [id] of state.sources)if(!state.layers.some(l=>l.sourceId===id))state.sources.delete(id);state.multi=new Set();state.selected=state.layers.at(-1)?.id||null;if(!state.layers.length){state.scene={w:0,h:0};state.mode='normal';state.view={zoom:1,x:0,y:0};}updateControls();msg('Capas eliminadas del proyecto.')}

